"""tables.md from design.json, runs/*/results.json, runs/llm_*/additive.json and runs/llm_*/factorial.json (bump goals).

    .venv/bin/python studies/8_language_models/bump_goals/tables.py
"""

from __future__ import annotations

import argparse, json
from pathlib import Path

import numpy as np

HERE = Path(__file__).resolve().parent
ci = lambda x: f"{x[0]:.2f}–{x[1]:.2f}"


def main():
    ap = argparse.ArgumentParser(); ap.add_argument("--out", default=str(HERE)); a = ap.parse_args()
    design = json.loads((HERE / "design.json").read_text()); K = design["K"]
    runs = {p.parent.name: json.loads(p.read_text()) for p in sorted((HERE / "runs").glob("*/results.json"))}
    adds = {p.parent.name: json.loads(p.read_text()) for p in sorted((HERE / "runs").glob("llm_*/additive.json"))}
    facs = {p.parent.name: json.loads(p.read_text()) for p in sorted((HERE / "runs").glob("llm_*/factorial.json"))}
    opt = design["per_goal"]; c = design["ceiling"]
    L = ["# Bump goals: tables", "", f"Generated by `tables.py`. Four goals at " + ", ".join(f"(x {g[0]}, y {g[1]})" for g in design["goals"]) + f"; the exact optimum per goal returns " + ", ".join(f"{r['optimal']['ret']:.3f}" for r in opt) + f" (mean {np.mean([r['optimal']['ret'] for r in opt]):.3f}) with success " + ", ".join(f"{r['optimal']['success']:.3f}" for r in opt) +
         f". The additive ceiling on the optimum's decisions under every goal: additive {c['additive']:.3f}, goal-blind {c['goal_blind']:.3f}, history-blind {c['history_blind']:.3f}; the optimal action depends on the goal in {design['goal_dependent']:.3f} of decisions.", ""]
    L += ["## Trained on the task (means over the four goals; per goal in brackets)", "", "| model, episodes | success | return | teacher-forced decision optimality | by set size 1 / 2–4 / 5–16 / > 16 (mean over goals) | minutes |", "|---|---|---|---|---|---|"]
    for k in sorted(runs, key=lambda k: (k.split("_")[0], int(k.split("_")[1]))):
        r = runs[k]; pg = r["per_goal"]; bs = {b: np.mean([g["teacher_forced"]["by_size"][b] for g in pg]) for b in ("1", "2-4", "5-16", ">16")}
        L.append(f"| {k.replace('_', ', ')} | {r['mean']['success']:.3f} ({' '.join(f'{g['closed_loop']['success']:.2f}' for g in pg)}) | {r['mean']['ret']:.3f} ({' '.join(f'{g['closed_loop']['ret']:.2f}' for g in pg)}) | {r['mean']['optimal']:.3f} ({' '.join(f'{g['teacher_forced']['optimal']:.2f}' for g in pg)}) | {bs['1']:.2f} / {bs['2-4']:.2f} / {bs['5-16']:.2f} / {bs['>16']:.2f} | {r['seconds'] / 60:.0f} |")
    L.append(f"| exact optimum | {np.mean([r['optimal']['success'] for r in opt]):.3f} | {np.mean([r['optimal']['ret'] for r in opt]):.3f} | 1 | | |"); L.append("")
    for k, ad in adds.items():
        sh, off, on = ad["shares"], ad["offline"], ad["online"]
        L += [f"## The additive decomposition of {k}", "", f"{ad['n']} decisions from the optimum's trajectories under every goal; the centred logits under each of the four goals with the history fixed, L(h, g) = H(h) + G(g, step) + I(h, g).", "",
              f"* Variance shares: history H {sh['history']:.3f}, goal G {sh['goal']:.3f}, interaction I {sh['interaction']:.3f}; the interaction's share by goal-free set size 1 / 2–4 / 5–16 / > 16: " + " / ".join(f"{ad['interaction_by_size'][b]:.3f}" for b in ("1", "2-4", "5-16", ">16")) + ".",
              f"* Goal-dependent decisions (the argmax differs between goals): the model {ad['goal_dependent']['model']:.3f}, the optimum {ad['goal_dependent']['optimum']:.3f}.", "",
              "| policy | offline: optimal in decision-goal pairs | by set size 1 / 2–4 / 5–16 / > 16 | online: return (mean over goals) | success |", "|---|---|---|---|---|"]
        for name, lab in (("model", "the model's own logits"), ("additive", "**additive**: argmax H(h) + G(g, step)"), ("goal_blind", "goal-blind: argmax H(h)")):
            bs = ad["offline_by_size"][name]; L.append(f"| {lab} | {off[name]:.3f} | {bs['1']:.2f} / {bs['2-4']:.2f} / {bs['5-16']:.2f} / {bs['>16']:.2f} | {on[name]['ret']:.3f} | {on[name]['success']:.3f} |")
        L += [f"| the exact additive ceiling / goal-blind ceiling | {c['additive']:.3f} / {c['goal_blind']:.3f} | | | |", f"| the exact optimum | 1 | | {ad['optimum_ret']:.3f} | |", "",
              f"**Recovery of the goal-directed return by the additive policy: {ad['recovery']:.3f}** ((additive − goal-blind) / (model − goal-blind); maze10: 0.81).", ""]
    for k, fc in facs.items():
        L += [f"## Goal swaps in the residual stream of {k}", "", f"{fc['n_pairs']} same-step history pairs × 6 goal pairs; the decision token's residual entering each layer patched from the other cells (to source among quartets where the targets differ; both type: to q_h = the source's history under the recipient's goal, to q_g = the recipient's history under the source's goal). The factorial experiment's unique attribution on four-distinct quartets is undefined here: with three actions no quartet has four different decisions. Site 24 is the residual after the last layer, which fixes the logits (a check, not a layer entrance); the best layer is chosen among sites 0–23.", "",
              "| site (residual entering layer) | goal swap (same history): to source | logit transfer | history swap (same goal): to source | logit transfer | both: to source | both: to q_h | both: to q_g |", "|---|---|---|---|---|---|---|---|"]
        for r in fc["by_layer"]:
            g = lambda k_: r.get(k_, float("nan"))
            L.append(f"| {r['layer']} | {g('same_hist_to_source'):.2f} | {g('same_hist_transfer'):.2f} | {g('same_goal_to_source'):.2f} | {g('same_goal_transfer'):.2f} | {g('both_to_source'):.2f} | {g('both_to_qh'):.2f} | {g('both_to_qg'):.2f} |")
        if "goal_swap_at_best" in fc:
            L += ["", f"At layer {fc['best_layer']}, the goal swap by three installed states (same history; switched among goal-dependent decisions, logit transfer, R² for the natural state under B):", "", "| installed state | switched | logit transfer | R² |", "|---|---|---|---|"]
            for name, v in fc["goal_swap_at_best"].items(): L.append(f"| {name} | {v['switch']:.3f} | {v['transfer']:.2f} | {v['r2']:.2f} |")
        L.append("")
    ph = HERE / "posthoc_ceiling.json"
    if ph.exists():
        pc = json.loads(ph.read_text()); r0 = pc["rounds"][0]; rl = pc["rounds"][-1]
        L += ["## Post hoc: the exact additive ceiling rule run online (`posthoc_ceiling.md`)", "", f"The best rule argmax h[goal-free set] + g[goal, step], fitted on the optimum's decisions (the ceiling), run in the environment on the test starts; then refitted on its own online decisions as well, {len(pc['rounds']) - 1} rounds. An unseen set falls back to argmax g[goal, step]. Recovery here is (additive − goal-blind) / (optimum − goal-blind), both rules exact.", "",
              "| fit | offline optimal on the optimum's decisions | by set size 1 / 2–4 / 5–16 / > 16 | online return | success | unseen sets | goal-blind rule online: return / success | recovery |", "|---|---|---|---|---|---|---|---|"]
        for row in pc["rounds"]:
            r = row["additive"]; L.append(f"| {'the optimum\'s decisions' if row['round'] == 0 else f'+ own decisions, round {row['round']}'} | {r['offline_optimum']:.3f} | " + " / ".join(f"{r['offline_by_size'][b]:.2f}" for b in ("1", "2-4", "5-16", ">16")) + f" | {r['online']['ret']:.3f} | {r['online']['success']:.3f} | {r['online']['unseen']:.2f} | {row['goal_blind']['online']['ret']:.3f} / {row['goal_blind']['online']['success']:.3f} | {row['recovery']:.3f} |")
        L.append(f"| the history-blind rule g[goal, step] | {r0['history_blind']['offline_optimum']:.3f} | | {r0['history_blind']['online']['ret']:.3f} | {r0['history_blind']['online']['success']:.3f} | | | |"); L.append("")
    # scorecard
    L += ["## Scorecard", "", "| | criterion | numbers | held |", "|---|---|---|---|"]
    if "llm_40000" in runs:
        r = runs["llm_40000"]; lo = min(g["closed_loop"]["success_ci"][0] for g in r["per_goal"])
        L.append(f"| L-OPT | fine-tuned at 40 000: success ≥ 0.98 (mean over goals) and decision optimality ≥ 0.99 | success {r['mean']['success']:.3f} (lowest goal's lower CI {lo:.2f}), optimality {r['mean']['optimal']:.3f} | {'yes' if r['mean']['success'] >= 0.98 and r['mean']['optimal'] >= 0.99 else 'no'} |")
    if "tfm_40000" in runs:
        r = runs["tfm_40000"]; L.append(f"| SCRATCH | from-scratch transformer at 40 000: success < 0.5 | {r['mean']['success']:.3f} | {'yes' if r['mean']['success'] < 0.5 else 'no'} |")
    if "llm_40000" in adds:
        ad = adds["llm_40000"]
        L.append(f"| ADD-OFF | additive policy offline optimal ≥ 0.80 | {ad['offline']['additive']:.3f} (ceiling {c['additive']:.3f}) | {'yes' if ad['offline']['additive'] >= 0.80 else 'no'} |")
        L.append(f"| ADD-ON | online recovery between 0.5 and 0.85 | {ad['recovery']:.3f} | {'yes' if 0.5 <= ad['recovery'] <= 0.85 else 'no'} |")
        L.append(f"| INT | interaction share > 0.15 | {ad['shares']['interaction']:.3f} | {'yes' if ad['shares']['interaction'] > 0.15 else 'no'} |")
    if "llm_40000" in facs and "goal_swap_at_best" in facs["llm_40000"]:
        fc = facs["llm_40000"]; sw = fc["goal_swap_at_best"]; nat = sw["natural"]["switch"]
        L.append(f"| SWAP | best-layer goal swap switches ≥ 0.85 | layer {fc['best_layer']}: {nat:.3f} | {'yes' if nat >= 0.85 else 'no'} |")
        L.append(f"| G-OFF | mean offset ≤ 0.75 × the whole swap | {sw['mean_offset']['switch']:.3f} / {nat:.3f} = {sw['mean_offset']['switch'] / max(nat, 1e-9):.3f} | {'yes' if sw['mean_offset']['switch'] <= 0.75 * nat else 'no'} |")
        L.append(f"| MAP | linear map ≥ 0.90 × the whole swap | {sw['linear_map']['switch']:.3f} / {nat:.3f} = {sw['linear_map']['switch'] / max(nat, 1e-9):.3f} | {'yes' if sw['linear_map']['switch'] >= 0.90 * nat else 'no'} |")
    Path(a.out, "tables.md").write_text("\n".join(L) + "\n"); print("\n".join(L))


if __name__ == "__main__":
    main()
